insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 1, 'What quantities do the two axes of the cost time curve carry on the golden programme?', '["Elapsed hours from spud across the bottom, and cumulative base cost in USD climbing up the side.", "Rotating hours across the bottom and cost per metre up the side.", "Measured depth in metres across the bottom, with the authorised total including its contingency provision plotted up the side.", "Calendar dates across the bottom and the tangible share of the estimate up the side."]'::jsonb, 0, 'The golden curve therefore runs from 0 hours and 0 USD to 432 hours and 5,380,000 USD.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 2, 'Why does the horizontal axis include the 48 hours of non-productive allowance rather than counting only the 384 productive hours?', '["Because the allowance is a contractual entitlement that the rig owner is permitted to bill separately.", "Because the engine has no way of separating the productive hours from the allowance once the schedule has been rolled up into a single elapsed figure.", "Money leaves the account during non-productive hours just as it does while the bit turns, so both must be shown.", "Because non-productive hours are the only hours in which lump lines are allowed to land."]'::jsonb, 2, 'An axis of productive time alone would flatter every well drawn on it, and would flatter the troubled ones most.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 3, 'Which question does the cost time curve answer that the authorisation for expenditure does not?', '["Which of the cost lines are tangible and which are intangible.", "Whether the money committed by any given hour of the well matches what the programme said it would be.", "How large a provision should be carried above the base estimate before the document goes forward for signature.", "Which contractor holds each of the nine lines in the estimate."]'::jsonb, 1, 'The comparison is available to a night supervisor with a watch, and needs no accounting close to produce.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 4, 'What does the shape of the plotted curve look like on a programme of ten activities?', '["A smooth exponential rise that steepens towards total depth.", "A single straight line from spud to the final point, because every cost line in the estimate accrues at a constant rate throughout the whole well.", "A staircase of equal steps, one for each of the ten activities.", "A run of straight segments, one for each activity, broken by vertical steps wherever a lump line lands."]'::jsonb, 3, 'Read the shape carefully and you can often name the activity without being told which one it is.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 5, 'How does a per day cost line contribute to the cumulative figure at any point along the curve?', '["Its rate is multiplied by the metres of hole made so far.", "Its rate is multiplied by the elapsed days reached so far, so it accrues linearly in elapsed time.", "Its whole value is placed at the end of the activity whose duration was the longest one in the programme, as a single vertical step.", "Its rate is multiplied by the productive days only, leaving the allowance unbilled."]'::jsonb, 1, 'The rig at 100,000 USD and the services spread at 60,000 give 160,000 USD of per day billing between them.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 6, 'On what basis does the mud and consumables line at 150 USD per metre accrue along the curve?', '["It bills on metres of hole actually made, which is not the same as depth reached and is not time at all.", "It bills evenly across the whole elapsed duration of the well.", "It bills on the measured depth of the deepest point reached so far, so a round trip back to surface leaves the accrual unchanged at that depth figure.", "It bills as a single step once total depth has been reached."]'::jsonb, 0, 'Casing runs and trips make no hole, so this line stays flat through them while the per day lines keep climbing.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 7, 'Where does a lump line appear on the curve when it names an activity to link to?', '["It is spread evenly across the duration of that activity.", "It is divided between the activity it names and the one that follows it, in proportion to the elapsed hours each of those two activities carries.", "It arrives whole, as a vertical step at the end of that activity, having accrued nothing beforehand.", "It is placed at spud regardless of which activity it names."]'::jsonb, 2, 'Five lump lines carry 2,050,000 USD between them on the golden case, which is most of its step height.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 8, 'Why does the published curve for a 432 hour well hold exactly eleven points?', '["The well is 18 days long and a point is written for every day.", "Eleven is the fixed grid size the engine uses for a curve of any length.", "The engine samples on a regular time slice and eleven slices are enough to hold the shape of a well of that length.", "The engine evaluates at spud and at the end of each of the ten activities, and nowhere else along the well."]'::jsonb, 3, 'Between two boundaries both running rates are constant, so an intermediate point would add nothing readable.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 9, 'Why is the cumulative figure at the end of the first activity 180,000 USD after 27 elapsed hours?', '["No hole has been made yet, so the per day lines alone have billed, across 27 hours of rig move and spud.", "The mud line has billed on the first 500 m of surface hole.", "A lump line for the rig move has landed at the end of that activity and been added to the running per day accrual reached at that boundary.", "The figure carries a share of the contingency provision allotted to spud."]'::jsonb, 0, '27 hours is 1.125 days, which at 160,000 USD per day gives the 180,000 USD exactly.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 10, 'How does the 480,000 USD rise across the 13-3/8in casing activity divide between its two causes?', '["It is 480,000 USD of per day accrual and no lump at all.", "It is a single lump of 480,000 USD covering the casing string, the cement job and the services around it, landing at the end of that activity.", "It is 300,000 USD of accrual with a 180,000 USD lump on top.", "The cementing services lump of 300,000 USD arrives whole, and 180,000 USD accrues over the 27 hours taken."]'::jsonb, 3, 'Only the accrual half would grow if that casing job overran, because a lump does not care how long the work took.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 11, 'What does the published checkpoint at elapsed hour 211.5 fix about the state of the well?', '["The hole stands at total depth with the completion still to run.", "The hole stands at 500 m, because only the surface section has been drilled and cased by that point in the programme.", "The hole stands at 2,000 m of the 3,000 m planned, with 211.5 of the 432 scheduled hours gone.", "The hole stands at 2,000 m and the well is exactly half way through its scheduled hours."]'::jsonb, 2, 'Reproducing that checkpoint from the programme and the cost lines returns the same figure, absolute error 0 USD.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 12, 'Against which of the AFE figures should the 2,260,000 USD committed at the checkpoint be read?', '["Against the tangible subtotal of 1,050,000 USD.", "Against the base of 5,380,000 USD, since the provision above it never appears anywhere on the curve.", "Against the approved total of 5,918,000 USD, because that is the figure the operator is actually authorised to spend on the well.", "Against the intangible subtotal of 4,330,000 USD."]'::jsonb, 1, 'Two lumps have landed by that hour and three are still ahead, worth 1,500,000 USD between them.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 13, 'A well sits above the plan line at a given hour. What are the two quite different stories that can put it there?', '["It is running late and the per day lines keep billing, or it is on depth and simply spending faster.", "Either the contingency has been drawn down or the base was raised.", "Either the rig has been off contract for part of the period or the operator has chosen to pay several of the lump lines earlier than the programme assumed they would fall.", "Either the schedule slipped or the non-productive allowance was set too low."]'::jsonb, 0, 'One story compounds with every further day and the other does not, which is why the depth track has to sit beside it.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 14, 'Why is a well sitting below the plan line not yet evidence of a saving?', '["Because the base curve already carries a non-productive allowance.", "If it is under on cost because the section has not been drilled yet, the money is deferred and still owed.", "Because the cumulative figure is stated in cash committed rather than in cash actually paid out, and invoices from the service companies always arrive some weeks in arrears.", "Because lump lines are excluded from the curve until the well reaches total depth."]'::jsonb, 1, 'Under on cost and on depth is a genuine gain, so the honest reading pairs this chart with the time depth curve.'),
  ('wellcost', 'advanced', 'module', 'm01-the-cost-time-curve', 15, 'Can a well that finishes a little above the plan line still land inside its approved authority?', '["No, since any hour spent above the line consumes authority directly.", "No, because the curve and the authorisation are built from the same nine cost lines and therefore always finish on precisely the same figure.", "Yes, because the curve ends on the base while the approval carries a further 538,000 USD of provision.", "Yes, but only if the overrun happened during a flat activity."]'::jsonb, 2, 'Tracking against what was costed and holding enough authority to finish are two separate questions.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 1, 'On which of the golden AFE figures does the last point of the cost time curve land?', '["On the approved total, since that is the figure signed for.", "On the base of 5,380,000 USD, and it never approaches the 5,918,000 USD carried for approval.", "On the intangible subtotal, because the per day and per metre lines that drive the accrual are all classed as intangible on this estimate.", "On the base plus half of the provision, as a working compromise."]'::jsonb, 1, 'The engine states this as a design commitment, with contingency excluded from the accrual by intent.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 2, 'What is the absolute error between the curve endpoint and the AFE base subtotal on the golden case?', '["Around 538,000 dollars, being the size of the provision.", "A few dollars, arising from rounding in the per day accrual.", "It is not fixed at all, because the size of the error depends on how many activity boundaries the programme happens to contain.", "Zero dollars, and the comparison is a strict equality rather than an agreement inside a tolerance."]'::jsonb, 3, 'A tolerance forces an argument about what drift is acceptable, and zero admits no such conversation.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 3, 'What does the difference between the curve endpoint and the approved total consist of?', '["The contingency provision and nothing else, which on the golden case is exactly 538,000 dollars.", "The tangible lines, which are held outside the accrual.", "The provision together with the non-productive allowance, both of which sit above the accruing part of the estimate rather than inside it.", "The lump lines that had not yet landed by the final boundary."]'::jsonb, 0, 'That makes recovering the provision from a published curve a matter of one subtraction.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 4, 'Over how many combinations was the endpoint identity checked, and with what worst result?', '["Three combinations, with a worst error of a few hundred dollars.", "One combination only, the golden case itself.", "Five non-productive fractions crossed with four contingency fractions, twenty in all, worst error 0 USD.", "Twenty combinations, of which most returned zero while the two most extreme ones drifted by a few thousand dollars each."]'::jsonb, 2, 'In all twenty the gap from curve to total also equalled the contingency exactly, not merely approximately.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 5, 'What happens to the endpoint as the contingency fraction is raised while everything else is held still?', '["It rises in proportion to the fraction that was set.", "It rises, but only by the tangible share of the provision.", "It falls, since a larger provision reduces the base that the accruing lines are permitted to bill against over the schedule.", "Nothing at all. It stays on the same dollar, because the provision never accrues anywhere on the curve."]'::jsonb, 3, 'At a non-productive fraction of 0.125 the endpoint holds at 5,380,000 USD while the totals run from 5,380,000 to 8,070,000.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 6, 'Why does the endpoint move when the non-productive fraction is changed?', '["Because the allowance is itself a lump line on the estimate.", "A larger allowance stretches the schedule, and more elapsed days means more per day billing on the curve.", "Because the per metre line bills against elapsed hours as well as against the metres of hole that have actually been made by that point.", "Because raising the allowance raises the contingency alongside it."]'::jsonb, 1, 'Across the sweep the endpoint runs from 5,060,000 USD at a fraction of 0 to 6,340,000 USD at 0.5.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 7, 'What is true of the final elapsed hour of the curve compared with the schedule it was built from?', '["The curve runs one boundary past the schedule to hold the lumps.", "The curve stops at the last productive hour, leaving the non-productive allowance beyond its right hand end where nothing is plotted.", "They agree with an error of zero hours, so no cost accrues in a period the schedule does not contain.", "The two agree only when the non-productive fraction is zero."]'::jsonb, 2, 'Spreadsheets often fail this, with a cumulative column running one row past the schedule to park a stray lump.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 8, 'What is the argument for carrying the base on the curve rather than the total?', '["Every dollar of the base attaches to an activity, a day or a metre, so each one has a place on a time axis.", "The base is the larger of the two figures on any estimate.", "The base is the only part of the estimate that the operations team is permitted to see before the well has been formally sanctioned.", "The base is stated in cash terms while the total is stated in accrual terms."]'::jsonb, 0, 'A provision covers events outside the programme, so there is no hour at which any of it becomes owed.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 9, 'What would spreading the provision evenly across the 432 hours actually assert about the well?', '["That the provision has already been committed at spud.", "That the provision belongs to the flat activities alone.", "That trouble is concentrated at handover, which is the one part of the programme where operational surprises are least likely to appear.", "That trouble arrives at a constant rate through the well, which is a picture of a well nobody has drilled."]'::jsonb, 3, 'Placing it all at spud instead makes the plan line unreachable from hour zero, which fails just as badly.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 10, 'If the provision did accrue, where would a well running exactly to programme sit against the plan line?', '["Below it at every hour of its life, by a growing amount, and it would finish 538,000 dollars under.", "Exactly on it, since running to programme is what the line describes.", "Above it throughout, because the accruing provision would be added to the committed figure at every hour that the well was being drilled.", "Below it early and above it late, crossing near the middle."]'::jsonb, 0, 'A crew that beats the line every single day soon stops reading it, which is how an operations chart dies.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 11, 'Where does the 538,000 dollar provision rank among the nine lines of the golden AFE?', '["First, ahead of every contracted line on the estimate.", "Fourth, behind the rig dayrate, the integrated services spread, and casing and accessories.", "Ninth and smallest, which is why it can safely be smeared into the slope of the accrual rather than shown as a line of its own.", "Sixth, just behind the wireline logging lump."]'::jsonb, 1, 'The three lines above it are 1,800,000, 1,080,000 and 800,000 dollars, so a line that size deserves to be seen.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 12, 'How is the one line audit of somebody else''s cost model actually carried out?', '["Recompute every activity duration from the rates upward.", "Compare the tangible and intangible subtotals against each other.", "Take the last cell of the cumulative column, take the base subtotal, and subtract one from the other.", "Rebuild the whole accrual on a fixed time grid and check that it agrees with the published curve at every one of its points."]'::jsonb, 2, 'A zero answer says the accrual and the rollup agree, and it takes about five seconds without reading a formula.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 13, 'An inherited model ends above its base by roughly the size of its provision. What has most likely happened?', '["The contingency has been smeared into the accrual instead of being held off the curve as its own line.", "A lump line has been counted twice in the rollup.", "The per metre line has been billed against the total depth of the well rather than against the metres of hole that were actually made.", "The schedule has been rolled up before the allowance was applied."]'::jsonb, 0, 'That is the common failure, and it is exactly the one the identity was written to catch.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 14, 'A model finishes short of its base by an amount with no clean interpretation. Which suspect is worth checking first?', '["A contingency fraction entered as a percentage rather than a fraction.", "A lump line linked to the wrong activity, which shifts a step sideways.", "A per day rate applied over productive hours only, which lands short by exactly the non-productive share.", "An activity duration entered in days where the programme expected hours, which would stretch the schedule and lift the endpoint well above the base."]'::jsonb, 2, 'On the golden case that mistake would drop 48 hours of the 432, which is 320,000 dollars of per day billing.'),
  ('wellcost', 'advanced', 'module', 'm02-the-endpoint-identity', 15, 'How does the engine treat a lump line whose activity reference does not exist in the programme?', '["It places the lump at the end of the last activity.", "It refuses the case outright with an error, rather than quietly dropping the line from the accrual.", "It spreads the value of that lump evenly across the whole schedule, so that the money still reaches the curve even though its intended home cannot be found.", "It keeps the lump in the rollup but leaves it off the curve."]'::jsonb, 1, 'A lump naming no activity at all is a different case and is placed at spud, so the endpoint still lands on the base.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 1, 'Into which three families do the uncertain inputs of a well cost model fall?', '["Tangible items, intangible items and the provision above them.", "Drilling hours, tripping hours and casing hours.", "Rates that turn metres into hours, durations stated directly in hours, and unit costs that are prices.", "Geological inputs, mechanical inputs and commercial inputs, each of which is owned by a different discipline within the well delivery team."]'::jsonb, 2, 'On the golden programme only the rig move at 24 hours and the completion at 60 carry a duration with no rate behind it.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 2, 'What makes a range on an input honest rather than decorative?', '["Both of its endpoints can be defended from something, such as offset wells, recent operations or quotes.", "It is at least as wide as plus or minus twenty percent.", "It is centred on the deterministic value already used in the plan.", "It is wide enough that the resulting distribution looks suitably uncertain when the percentiles are read off the finished chart."]'::jsonb, 0, 'If you cannot say where a number came from, the honest course is to leave it deterministic and say so.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 3, 'Which inputs does the published risk case actually vary, and over how many iterations?', '["Every one of the eight cost lines, over 10,000 iterations.", "The ten activity durations, over 2,000 iterations.", "Two rates of penetration together with the non-productive allowance and the contingency fraction, over 2,000 iterations at a fixed seed.", "Two rates of penetration, one day rate and one lump, over 2,000 iterations run at seed 42."]'::jsonb, 3, 'It is a deliberately small set, and each of the four is a number somebody could be asked to justify.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 4, 'Why does the published case hold the non-productive and contingency fractions fixed instead of sampling them?', '["Because neither of them is permitted to change once an estimate has been issued.", "Both are already provisions against things going wrong, so sampling them counts the same worry twice.", "Because the shared sampling module has no distribution that can be applied to a quantity expressed as a fraction rather than as a rate or a price.", "Because they have no effect on the cost of the well."]'::jsonb, 1, 'The second count would also be invisible in the output, since nothing in the result says where the spread came from.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 5, 'Which of the four published uncertainties covers the widest ground relative to its own mode?', '["The production hole rate of penetration, running from 6 to 14 m per hour around a mode of 10.", "The rig day rate, which is a contracted commercial number.", "The completion services lump, running from 350,000 to 800,000 dollars.", "The intermediate hole rate of penetration, whose range of 10 to 22 m per hour spans a wider band in absolute terms than any of the other three."]'::jsonb, 0, 'The top of that range is more than twice its bottom, and it is what offset data looks like plotted by section.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 6, 'How many of the ten golden activities have their duration produced by a rate rather than stated outright?', '["Three, being the drill activities alone.", "Five, the drill activities and the two round trips.", "Eight of them, since the three drill activities, two round trips and three casing runs are all rate driven.", "All ten, because even the flat activities are internally built from an assumed working speed before their hours are reported."]'::jsonb, 2, 'The three drill activities alone hold 220 of the 384 productive hours on the programme.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 7, 'A 1,500 m interval is drilled at rates either side of its 15 m per hour mode. What shape does the resulting hours figure take?', '["It is symmetric, since hours move in step with the rate.", "It is deeply asymmetric. Halving the rate triples the hours, while doubling it saves only a quarter of them.", "It is asymmetric the other way, because a faster rate saves more hours than an equally large drop in rate can ever add to the total for that section.", "It is flat, because the interval fixes the hours whatever the rate."]'::jsonb, 1, 'At 5 m per hour the interval takes 300 hours, while even 40 m per hour, far outside the range, only reaches 37.5.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 8, 'Why is the triangular distribution the working default for this kind of estimate?', '["It is the only distribution the shared sampler carries.", "It is the distribution that produces the widest tails.", "It can be fitted to historical well data without any judgement being applied, which removes the estimator from the process altogether.", "It asks for a minimum, a most likely value and a maximum, which is how drilling engineers already talk."]'::jsonb, 3, 'Nobody has to estimate a standard deviation, or defend a parameter with no field meaning behind it.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 9, 'What are you asserting about the range when you place a triangular distribution on a rate of penetration?', '["That the bounds are hard, so a range of 10 to 22 says a rate above 22 m per hour is impossible.", "That the rate is equally likely anywhere between the bounds.", "That the bounds are soft and may be exceeded in the tails of the run, with a small but non zero density lying beyond each of the two endpoints.", "That the mode is also the average of the sampled values."]'::jsonb, 0, 'If those bounds cannot be defended, the canonical sampler also carries a lognormal, which has no upper bound at all.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 10, 'How does the mean of a triangular distribution relate to the three numbers used to specify it?', '["It equals the mode, which is why the mode is called most likely.", "It is the midpoint of the minimum and the maximum.", "It is their average, so it sits above the mode whenever the right hand tail is the longer one.", "It is the mode adjusted by one third of the difference between the two bounds, weighted towards whichever of them lies further from the peak."]'::jsonb, 2, 'On the closed form fixture that gap is real money: 1,530,000 USD against a modal answer of 1,500,000.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 11, 'Why should the rates of penetration in the intermediate and production sections not be sampled independently?', '["Because the two sections share a single measured depth reference.", "They are drilled by one rig and crew on one mud system, so a cause that slows one is often still present.", "Because the shared sampler cannot draw two triangular values in the same iteration unless a correlation has been declared between the two of them.", "Because the two rates have the same mode."]'::jsonb, 1, 'Correlation here is not a statistical decoration. It is the claim that the two draws share a cause.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 12, 'What does treating correlated sections as independent do to the reported result?', '["It leaves the mean almost untouched but narrows the tails, because good and bad draws cancel each other.", "It shifts the whole distribution towards the optimistic end.", "It widens the tails, since two inputs moving freely against one another can reach combinations that a correlated pair would never be able to produce.", "It has no effect once the iteration count is high enough."]'::jsonb, 0, 'Understating spread is the dangerous direction, given that the run exists to size a provision against the bad tail.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 13, 'How does the canonical module impose a declared correlation on the sampled inputs?', '["It sorts the drawn values of each input into matching rank order.", "It reweights the finished iterations so that the correlation appears in the summary statistics.", "It applies a Cholesky factor to independent normals, then pushes each value through its own inverse CDF.", "It replaces the triangular marginals with a single joint normal distribution whose covariance carries the declared correlation between the inputs."]'::jsonb, 2, 'Each input therefore keeps exactly the marginal that was specified, and the clamped diagonal avoids NaN on a matrix that is only just short of positive definite.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 14, 'Where does the Monte Carlo code that a risked well cost run depends on actually live?', '["Inside the well cost engine, alongside the closed form routines.", "In one shared module that every app imports, with the well cost engine itself deterministic throughout.", "In the panel component, so that each screen can hold the sampling behaviour its own charts happen to need.", "In a database function called once for each iteration."]'::jsonb, 1, 'A realisation is drawn by the module and the engine is then called once on it, two thousand times over.'),
  ('wellcost', 'advanced', 'module', 'm03-uncertainty', 15, 'What does the suite gain by keeping a single sampling implementation instead of several?', '["A faster run, because a shared module is compiled once.", "Freedom for each engine to choose the distributions that suit it.", "The ability to change a percentile convention in one app without any of the other apps that share the module being affected by it.", "One seed discipline, one percentile convention, and tornado charts from different apps that can be read together."]'::jsonb, 3, 'The module fixes the petroleum reading that P90 is the low case, taken as the tenth percentile of the sorted values.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 1, 'Hours plotted against rate of penetration on a fixed interval trace a hyperbola rather than a straight line. What produces that shape?', '["The rate sits in the denominator of every duration form, so time is proportional to one over the rate.", "A curvature correction is applied to drill rows by the engine.", "The non-productive allowance is stretched onto the productive hours, and that stretch is what bends an otherwise straight relationship.", "Pricing bends the relationship, because the cost of a metre rises once a section starts running slowly."]'::jsonb, 0, 'Rate multiplied by hours returns the interval, so the product stays at 1,500 at every point of the published sweep.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 2, 'The canonical sampler does not call the language''s own random number generator. What does it use instead?', '["A hardware entropy source, refreshed once per realisation.", "A generator built from an integer seed you supply, with every draw in the run coming out of that one stream.", "The system clock at the moment the run starts, which is recorded afterwards so that the same run can be repeated on request.", "A fixed table of pseudo random numbers shipped with the module, which is why every seed returns the same figures."]'::jsonb, 1, 'The contract is exact rather than approximate, so the same seed, iteration count, distributions and engine land on the same digits on any machine.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 3, 'A section planned at 15 m/hr on 1,500 m disappoints, first to 10 m/hr and then to 5 m/hr. What do those two identical steps cost?', '["Each of them costs 50 hours, one step after the other.", "The first costs 150 hours and the second costs 50, because the damage is largest while the planned rate is still close by.", "The first costs 50 hours and the second costs 150 hours, so the same disappointment hurts three times as much.", "Both cost 100 hours, which is the planned duration of the section itself."]'::jsonb, 2, 'Hours relative to the plan run 1.5 at 10 m/hr and 3 at 5 m/hr, so halving the rate doubles the time on each occasion.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 4, 'A symmetric window of plus or minus 5 m/hr is drawn around a planned 15 m/hr on the 1,500 m intermediate section. What does it deliver in hours?', '["It gains 50 hours and loses 25, favouring the upside by two to one.", "It delivers 25 hours either way, since a symmetric window in rate stays symmetric in hours.", "It loses 50 hours and gains 50 hours, so the two sides cancel and the expected schedule is unchanged by the window.", "It loses 50 hours on the downside against 25 hours gained on the upside, so the loss is exactly double the gain."]'::jsonb, 3, 'Widening the window to plus or minus 10 m/hr makes the imbalance worse still, at 200 hours lost against 40 gained.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 5, 'A casing run at 2,000 m carries 19 hours of flat time. Raising the run speed towards absurd values, what does the activity refuse to go below?', '["It settles on 21 hours, the figure the activity reaches at 1,000 m/hr.", "It settles on the 19 flat hours, which no improvement in run speed can reach because they carry no speed.", "It settles on zero hours, because a high enough speed eventually removes the running term and the flat term along with it.", "It has no floor at all, since every hour in the activity responds to the speed the crew achieves."]'::jsonb, 1, 'The published sweep reads 39 hours at 100 m/hr and 21 hours at 1,000 m/hr, so nine tenths of the speed gain buys only 18 hours.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 6, 'The Monte Carlo fixture shows a mean cost 30,000 USD above its modal base of 1,500,000 USD, a fraction of 0.02. What causes that gap?', '["Input skew alone, because all four of the uncertainties in that fixture enter the cost through addition or a constant.", "Convexity in the map from rate of penetration to hours.", "Convexity and input skew together, in roughly equal parts, since a Monte Carlo run on a cost always carries both of them at once.", "Sampling noise at 2,000 iterations, which would shrink towards zero if the run were repeated with far more draws."]'::jsonb, 0, 'The fixture varies three flat durations and one lump value, and a flat duration never divides anything, so nothing in it bends.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 7, 'A colleague points at the fixture''s 2 per cent gap and calls it a demonstration of convexity. Where is convexity actually demonstrated in this module?', '["On the fixture''s uncertain lump, which has a mean above its mode.", "On the non-productive allowance, since stretching productive time by a fraction is the only nonlinear step anywhere in the engine.", "On the rate of penetration sweep and on the two uncertain rates of the golden case, none of which the fixture contains.", "Nowhere in this module, because convexity is asserted rather than shown on any published figure."]'::jsonb, 2, 'The two effects can be separated precisely because one fixture is linear and one case is not, so each lift can be seen without the other.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 8, 'Hours on a section swing by plus 50 and minus 25 around the plan. What does the cost do with that asymmetry once the per-day lines are applied?', '["It doubles the asymmetry, since money bends a second time.", "It removes the asymmetry, because the per-metre and lump lines are unaffected by a slip and dilute the swing away entirely.", "It reverses the asymmetry, leaving the saving worth more in money than the overrun costs.", "It inherits the same shape untouched, because 160,000 USD per elapsed day applies equally to hours lost and hours gained."]'::jsonb, 3, 'All the bending happened in the step from rate to time, and the golden estimate carries 53.53 per cent of its base on per-day lines.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 9, 'Why can the mean and the variance of the Monte Carlo fixture be written down exactly, with no sample taken at all?', '["Its total cost is a linear combination of the four inputs, and linear combinations have textbook moments.", "Its four inputs are triangular, and triangular distributions are the only ones with published moments.", "Its iteration count of 2,000 is high enough that the sampled figures and the closed form figures agree to every digit printed.", "Its uncertainties are independent, and independence on its own is what allows a mean to be written in closed form."]'::jsonb, 0, 'A mean of a sum is the sum of the means whatever the shapes, while the variance needs the independence as well.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 10, 'A risked total is going into an approval pack. What has to travel beside it for a reviewer to rebuild the figure without asking anything?', '["The seed alone, since it fixes every draw in the run.", "The seed and the iteration count, every distribution with its parameters, any correlation, and the engine and case version.", "The mean, the median and the standard deviation, which between them describe the sampled distribution closely enough to be reconstructed.", "The deterministic base cost and the contingency fraction that was applied to it."]'::jsonb, 1, 'The seed is the item that goes missing first, because it reads like plumbing rather than content, and dropping it makes the number uncheckable.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 11, 'One flat duration in a case is replaced by an uncertain rate of penetration. Why does the closed form for the mean stop working?', '["The rate is triangular, and a triangular has no defined mean.", "The engine begins rounding the schedule to whole days once a rate is uncertain, and rounding has no closed form expression at all.", "The expectation of one over a variable is not one over its expectation, so the mean rate returns the wrong mean time.", "The mean is still correct, and only the variance becomes impossible to write down in closed form."]'::jsonb, 2, 'The error also runs in one direction every time, so the mistake is a bias rather than a scatter that averages away.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 12, 'Two sections of the golden case both carry uncertain rates and share a per-day exposure. What would writing its cost variance in closed form require?', '["The correlation coefficient between the two uncertain rates.", "Nothing beyond the four input variances, which can be added once each is scaled by the square of its coefficient.", "A larger iteration count, since the variance of the total is estimated from the sample rather than from the input distributions.", "Moments of a sum of reciprocals of different triangulars, including the expectation of one over rate squared."]'::jsonb, 3, 'The two rate uncertainties sit on the intermediate hole and on the production hole, and no standard result covers that combination.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 13, 'An engineer puts a range of plus or minus twenty per cent around a finished base cost of 5,380,000 USD and calls the result a risked estimate. What is wrong with it?', '["It is a shape drawn on the answer, so it cannot know that only part of the base moves when the schedule slips.", "It uses the base cost rather than the approved total as its centre.", "It is too narrow, and a range of plus or minus forty per cent around the same base would have been a defensible risked estimate instead.", "It omits the contingency line, which would have to be sampled separately before the total could be quoted."]'::jsonb, 0, 'On the golden case 53.53 per cent of the base is per-day exposed, and a range drawn on the total throws that split away.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 14, 'The golden risk case is configured for 2,000 iterations. What does raising the iteration count actually buy?', '["A distribution that is closer to the true one for the well.", "Less noise rather than more accuracy, with the sampling error on a percentile falling as one over the square root of the draws.", "A lower mean, because more draws reach further into the optimistic tail.", "Nothing measurable, since the seed rather than the number of draws is what fixes every figure the run reports."]'::jsonb, 1, 'Another decimal place on a quoted percentile costs about a hundred times the work, which is why convergence is judged rather than assumed.'),
  ('wellcost', 'advanced', 'module', 'm04-why-convexity-bites', 15, 'How should an engineer judge whether a quoted P50 has enough draws behind it?', '["Compare the sampled mean against the deterministic base cost.", "Check that the reported standard deviation has fallen below one tenth of the mean, which is the published convergence threshold for this engine.", "Rerun the case at other seeds and watch whether the figures intended for quotation move by a defensible amount.", "Raise the iteration count until the reported median stops changing in its final digit."]'::jsonb, 2, 'The tails need more draws than the middle does, so a figure read far out in the distribution is the one worth watching.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 1, 'Two thousand realisations have finished and a percentile is wanted. What does the sampler actually do to produce one?', '["It fits a distribution to the totals and evaluates that fit.", "It averages the realisations that fall near the wanted position, so that a single unusual draw cannot set the figure on its own.", "It sorts the totals from smallest to largest and reads the value at the index that far along the sorted list.", "It works the percentile out from the mean and the standard deviation of the run."]'::jsonb, 2, 'There is no formula involved at any point, which is why a percentile exists only once a run has finished.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 2, 'At 2,000 iterations, which reported figures wobble most when the same case is rerun at a different seed?', '["The extreme tails, because they are built from a small number of realisations while the middle is built from many.", "The mean, since every draw in the run contributes to it.", "All of them equally, because a change of seed redraws every realisation in the run and so disturbs every reported figure by the same proportion.", "None of them, since the iteration count rather than the seed fixes what a run reports."]'::jsonb, 0, 'Sampling error on a percentile falls as one over the square root of the draws, so a tail figure needs far more draws than the median does.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 3, 'A risked cost distribution is right skewed. What follows for the mean and the median, and why does the difference matter?', '["The median sits above the mean, since half the draws lie below it.", "The mean sits above the median, and quoting one while naming the other flatters or penalises the estimate.", "The two coincide, because the sorted list is symmetric about its middle once enough realisations have been collected to fill both tails.", "The mean sits above the median, and the two can be used interchangeably in an approval pack."]'::jsonb, 1, 'The mean matters to a portfolio because averages add across wells, while the median is the even money outcome for the single well in front of you.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 4, 'A reserves engineer and a cost engineer are both in the approval meeting. What does P90 mean to the reserves engineer?', '["The quantity that will not be exceeded nine times out of ten.", "The quantity nine tenths of the way up the sorted list of realisations, which is the large and optimistic end of the range.", "The average of the realisations lying in the upper tenth of the distribution.", "The quantity that will be exceeded nine times out of ten, which makes it the small and conservative figure."]'::jsonb, 3, 'Only P50 carries the same meaning in both conventions, which is why it is the one percentile that can be said out loud without a qualifier.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 5, 'Cost totals are pushed through the canonical sampler and the field named p90 is printed under a caption reading conservative case. What has been printed?', '["The cheapest tenth of the run, because the module labels for reserves and reads that field one tenth up the sorted list.", "The most expensive tenth of the run, correctly captioned.", "The median of the run, since the module recentres its tail fields whenever the quantity being sampled is a cost rather than a volume.", "A figure that cannot be interpreted, because the module refuses to return tail fields for cost quantities."]'::jsonb, 0, 'The estimate is not slightly wrong in that case, it is backwards by the whole width of the distribution.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 6, 'A tail figure arrives from another team with the bare label P10 beside it. What is the working rule?', '["Assume the cost convention, since the figure describes a cost.", "Assume the petroleum convention, because the shared sampler was written for reserves and every tool in the Suite draws from it.", "Treat it as unusable until the convention is stated, and write every figure of your own out in words.", "Compare it against the deterministic base cost, which will show which of the two conventions was intended by whoever sent it."]'::jsonb, 2, 'The full form is the cost that will not be exceeded nine times in ten, or the cost exceeded nine times in ten, written next to the figure.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 7, 'A deterministic estimate of 5,380,000 USD is described in review as realistic. What is the more useful statement about it?', '["The absolute error between it and the final value of the cost time curve.", "The percentile of its own risked distribution that it occupies, which is a fact rather than an opinion.", "The size of the contingency fraction chosen for it, since a larger provision is what turns an optimistic base case into a defensible plan.", "The share of the base carried on lines that bill per day rather than per metre."]'::jsonb, 1, 'The deterministic figure always had a position in its own distribution, and running the case is what makes that position visible.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 8, 'What is the procedure for locating a deterministic total inside its own risked distribution?', '["Divide the deterministic total by the sampled mean.", "Read the sampled median and compare it against the deterministic total.", "Subtract the contingency from the sampled mean, since contingency is the only line that separates a deterministic total from a sampled one.", "Run the case deterministically, run it sampled at a recorded seed, then count the realisations at or below the deterministic total."]'::jsonb, 3, 'The answer is a fraction, stated in a named convention, and the honest sentence is that the estimate covers roughly that share of the modelled outcomes.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 9, 'Two forces push a deterministic estimate below the middle of its own distribution. Which of them does the linear fixture display?', '["Input skew only, and it shows there as a gap of 30,000 USD, which is well under one standard deviation.", "Convexity only, since the fixture varies no rate of penetration.", "Both of them, which is what makes the fixture the natural place to demonstrate why a deterministic base case sits low in its own distribution.", "Neither of them, because a fixture built to close in form cannot show a gap between a modal run and a mean."]'::jsonb, 0, 'The fixture reports a standard deviation of 63868.354187866 USD, so the modal base sits below the mean by a fraction of that spread.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 10, 'A contingency fraction of 0.1 is applied to a base of 5,380,000 USD. What share of the approved total does the resulting provision represent?', '["A share of 0.1, which is what the fraction states.", "A share of 0.11111111111111111, which is the fraction divided by one less the fraction rather than by one plus it.", "A share of 0.09090909090909091, because a fraction of the base is the fraction over one plus itself of the total.", "A share that cannot be quoted, since the provision is a line of the total rather than a proportion of it."]'::jsonb, 2, 'At that fraction the 538,000 USD provision ranks fourth among the nine lines, at 0.29888888888888887 of the rig dayrate.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 11, 'Two wells share the same base cost and both carry a ten per cent contingency. Can they be said to carry the same confidence?', '["Yes, since the same fraction of the same base is the same money.", "No, because the percentile a provision reaches depends on the spread, and a fraction knows nothing about the spread.", "Yes, provided both estimates were built by the same team on the same engine, which is what makes two contingency fractions comparable.", "No, because the second well would need its fraction restated as a share of its total before the two could be compared."]'::jsonb, 1, 'A contingency fraction is an input while the confidence it delivers is an output, and nobody can quote the second by reading the first.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 12, 'What is the better habit for setting a provision, once the sampled distribution is available?', '["Decide the confidence the business will fund, read the cost at that percentile, and derive the fraction from it.", "Choose the fraction the last well in the field used.", "Choose the fraction at which the provision would overtake the largest contracted line, so that the cover is never smaller than any single item in the estimate.", "Choose the fraction that makes the total match the sampled mean of the run."]'::jsonb, 0, 'Worked in that direction the number has a reason behind it, and the sweep of fractions against percentiles becomes a menu rather than a precedent.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 13, 'A converged Monte Carlo run reports percentiles to the dollar. Which question does it leave completely unanswered?', '["Whether the engine evaluated each realisation correctly.", "Whether the seed and iteration count were recorded, which is the one part of a risked result the run itself cannot report back to you.", "Whether the totals were sorted before the percentiles were read off them.", "Whether the ranges fed into it were right, since nothing in the run compares an assumption against anything real."]'::jsonb, 3, 'The fixture''s coefficient of variation of 0.041744022345010456 is a property of four chosen triangulars, not a measurement of how variable a well is.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 14, 'The two uncertain rates on the golden case are sampled independently, although one rig and one crew drill both sections. What does that choice do to the result?', '["It raises the mean while leaving the tails where they were.", "It widens the tails, since independent draws can pair the worst intermediate section with the worst production section far more often.", "It leaves every mean where it was and shrinks the tails, so the reported spread is a lower bound rather than a neutral one.", "It has no effect on the distribution at all, because correlation is applied after the percentiles have been read."]'::jsonb, 2, 'Understating spread is the dangerous direction of error, given that the whole reason for the run is to size a provision against the bad tail.'),
  ('wellcost', 'advanced', 'module', 'm05-reading-a-risked-result', 15, 'Which kinds of cost event on this well are nowhere in the sampled variables, whatever the iteration count?', '["Any event that raises the cost of a per-metre line.", "Discrete events such as stuck pipe, a well control incident or a rig going off contract, none of which are modelled.", "Any event affecting the production hole, since only the intermediate section carries an uncertain rate of penetration in the published risk case.", "None, because the non-productive allowance is stretched across the whole programme and therefore covers every category of trouble time."]'::jsonb, 1, 'Trouble time enters as one smooth fraction stretching every activity, so the run cannot invent an event that the case never described.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 1, 'A team leader asks a graduate to state, in one sentence, the single idea that ties this whole tier together. What should the graduate say?', '["That estimates are uncertain and should carry a provision.", "That a single number hides something: a shape, a percentile, or a position in its own distribution.", "That the deterministic engine is accurate provided its closed forms have been checked against the published golden case row by row.", "That money spent is the only honest measure of progress on a well."]'::jsonb, 1, 'The tier is a sequence of demonstrations of that one point, and each module took a confident looking figure apart to make it.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 2, 'A supervisor bans the word convexity in a handover note and asks for the underlying fact in plain terms. Which sentence does the job?', '["Cost distributions have a long right tail.", "The mean of a triangular distribution sits above its mode whenever the maximum is further from the mode than the minimum is.", "Non-productive time is a stretch on productive time rather than a share of the elapsed clock, which is where the asymmetry originates.", "Time is the interval divided by the rate, so equal steps down in rate cost more hours than equal steps up save."]'::jsonb, 3, 'That is the fact behind the third thing a single number hides, since it is what puts the deterministic base below the middle of its own distribution.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A junior engineer opens a fresh case and starts by typing in the cost lines, meaning to add the activities afterwards. What is wrong with that order?', '["The basis of every line decides whether a slip touches it, so costs cannot be attached until the schedule exists.", "Nothing, since the engine accepts the two in either order.", "The engine refuses cost lines until at least one activity is present, so the work has to be abandoned and restarted from the activity list.", "Cost lines entered first are recorded as lump lines by default, and their basis cannot be changed once the schedule has been built around them."]'::jsonb, 0, 'A programme that runs at all has already passed structural checks, because the engine refuses a section that does not start where the last one finished.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A reviewer asks why an allowance of 0.5 was entered when the team wanted trouble time to be half the days on location. What is the correct reply?', '["The entry is correct, since the fraction splits the clock evenly.", "The entry is wrong because the engine caps the allowance below that value and will have silently reduced it before building the schedule.", "The fraction stretches productive time, so it delivers one third of the elapsed clock rather than one half.", "The entry is wrong because an allowance applies only to drilling activities, so the flat and casing rows dilute it across the programme."]'::jsonb, 2, 'A fraction f is f over one plus f of elapsed time, which is why the published 0.125 allowance is 11.11 per cent of the elapsed clock.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 5, 'An engineer inherits a cost model whose curve finishes a little short of the stated base subtotal and proposes to move on. What should be said?', '["Nothing, since a gap that small is within normal rounding.", "The identity is exact, so any non-zero error means the accrual is wrong and every figure downstream of it is suspect.", "That the gap should be added to the contingency line, which is the provision that exists precisely to absorb small unexplained differences in an inherited model.", "That the gap proves the provision was left out of the approved total rather than out of the curve."]'::jsonb, 1, 'The check is the first one in the sequence and it is not optional, because it costs one subtraction and validates the whole accrual.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 6, 'During a review a manager asks what the space between the plan line at the end of the well and the approved authority represents. What is the answer?', '["It is the contingency exactly, because the provision is never accrued at any point along the curve.", "It is the non-productive allowance carried on the programme.", "It is the tangible share of the estimate, which is committed at delivery rather than accrued over the elapsed hours the curve is drawn against.", "It is the amount by which the well is forecast to overrun its schedule, converted into money at the per-day rate."]'::jsonb, 0, 'That makes the gap a second check rather than a residual, since it can be compared against the stated provision line by line.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 7, 'A team agrees to run three standing checks on every risked estimate. In which order should they be applied?', '["Percentile labelling first, then the sampled mean, then the endpoint.", "Sampled mean first, then the curve endpoint, then the labelling of the percentiles that will be quoted in the approval pack.", "The three are independent of one another, so any order will do provided each is recorded.", "Curve endpoint against the base first, then the direction of the sampled mean, then the labelling of every percentile."]'::jsonb, 3, 'The endpoint comes first because a failed accrual makes every sampled figure downstream of it worthless before it is even read.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 8, 'An analyst reports a case whose only uncertainties are rates of penetration, and whose sampled mean comes back slightly below the deterministic total. What should happen next?', '["The result should be reported with the gap noted as a saving.", "The iteration count should be raised until the mean rises above the deterministic total, at which point the run can be quoted as converged.", "The result should not be reported, because rate uncertainties can only push the mean above the deterministic figure.", "The deterministic total should be rebuilt at the mode of each rate, since the two figures are not comparable until that is done."]'::jsonb, 2, 'The usual causes are reversed ranges, an uncertainty that never reaches the activity intended, or a run varying something other than what was believed.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A colleague has put a range on every input in a case, on the grounds that everything is uncertain. What is the better practice?', '["Vary only the quantities that are genuinely uncertain, and record where each minimum, mode and maximum came from.", "Vary only the inputs that appear in the largest cost line.", "Vary everything, because a wider set of ranges is always more conservative and no reviewer has ever objected to conservatism in an estimate.", "Vary nothing until offset data is available, and present the deterministic figure with a note attached."]'::jsonb, 0, 'The published case makes exactly that kind of choice, holding the allowance and the provision fixed while sampling four inputs.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 10, 'A reviewer switches on a positive correlation between two sections and expects the reported mean cost to rise. What actually happens?', '["The mean rises in proportion to the correlation applied.", "The means stay where they were and the tails widen, because each input keeps the marginal distribution it was given.", "The mean rises and the tails narrow, since correlated draws move together and therefore cancel less often than independent ones do.", "Nothing changes unless the correlation is applied before the ranges are set on the two sections concerned."]'::jsonb, 1, 'The copula imposes a joint pattern only, so the change belongs in the spread rather than anywhere in the centre of the distribution.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 11, 'A risked total is quoted in a meeting and someone asks how it could be rebuilt. The analyst remembers the settings but wrote none of them down. What is the problem?', '["There is no problem, since the case document holds the ranges.", "The problem is only that the analyst cannot demonstrate convergence, which would need several runs at different iteration counts rather than a written record.", "The problem is that the figure was quoted at all before the deterministic case had been approved.", "A sampled figure nobody else can reproduce is an anecdote, so the seed and iteration count belong beside the result."]'::jsonb, 3, 'Recording them alongside the distributions rather than in a comment is what the published case does, and it is why its figures repeat on any machine.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Two wells are reviewed after drilling. One simply came in over budget. On the other, the intermediate section took far longer than planned while every cost line billed as expected. Which teaches more?', '["The first, because the overrun is larger in money terms.", "Neither, since a completed well tells you nothing that was not already visible in the estimate that was approved for it.", "The second, because the variance has an owner in the schedule rather than sitting on the total.", "Both equally, provided the two wells were drilled by the same rig on similar programmes in the same field."]'::jsonb, 2, 'Filling the same activity structure with what the rig actually did is what turns an overrun into a finding rather than a total.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 13, 'A planner is costing the first well of a ten well campaign and copies the ranges and the day count from the sixth well of the last one. What is the objection?', '["Days per well fall along a learning curve, so the first well of a programme should not be costed like a later one.", "Ranges from another campaign are never transferable at all.", "The sixth well would have carried a lower contingency fraction, and the fraction is the part of an old estimate that should never be copied across into a new one.", "The objection is only that the rig rate will have changed since the previous campaign was drilled."]'::jsonb, 0, 'A database of offset wells with honest rates and non-productive time is what turns a range from an opinion into a measurement.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 14, 'An estimating team is praised for the most carefully risked estimate the business has produced, on a well drilled in the wrong place. What does that show?', '["That the ranges must have been drawn too narrow.", "That better estimating improves the number without improving the decision the number was built to support.", "That the estimate should have carried a larger provision, since a well in the wrong place is the clearest case of an uncertainty that no range on a rate of penetration can ever cover.", "That the risked figure was reported in the wrong convention."]'::jsonb, 1, 'Cost engineering earns its place by making the trade visible, so a precise account of money that should not have been spent is still precise.'),
  ('wellcost', 'advanced', 'module', 'm06-the-expert-reading', 15, 'At the end of this tier a mentor asks what the engineer can now claim to be able to do. Which claim is supported?', '["Predicting the cost of the next well in the field to within a few per cent.", "Choosing the drilling programme that will deliver the lowest cost per metre in a given formation sequence.", "Building a cost time curve, checking it against the base, and reading a risked estimate with its convention stated.", "Proving that a chosen set of ranges describes the well, once the run has converged at a recorded seed."]'::jsonb, 2, 'None of the tier makes a claim about the world outside the model, which is why the last of those is the one it explicitly refuses.'),
  ('wellcost', 'advanced', 'final', null, 1, 'Money on a rig climbed 340,000 USD between elapsed hour 49.5 and elapsed hour 63 while the bit made no hole. What produced that rise?', '["The per day lines billing 90,000 USD across 13.5 hours, plus the 250,000 USD wellhead lump landing whole.", "The mud line billing again on the 500 m of hole already made, which goes on accruing right through a casing run.", "The rig and services spread alone, because a casing run bills nothing else and a wellhead lump belongs to the activity that follows rather than this one.", "A per metre line accruing on depth reached instead of on metres drilled."]'::jsonb, 0, 'The two causes behave differently under an overrun, since only the accrual part grows if the casing job takes longer than costed.'),
  ('wellcost', 'advanced', 'final', null, 2, 'A superintendent asks for the chart replotted so that its horizontal axis counts only the 384 productive hours. What is the objection?', '["It would shift the curve endpoint away from the AFE base subtotal.", "The published checkpoint would then have to be quoted against the approved total rather than against the base.", "Money leaves the account during the 48 allowance hours too, so such an axis flatters every well drawn on it.", "Nothing is lost, because the per day lines bill only while the rig is productive and the mud line bills on metres, so the two axes carry identical information."]'::jsonb, 2, 'The flattery is worst on the troubled wells, which are exactly the ones an operations chart exists to expose.'),
  ('wellcost', 'advanced', 'final', null, 3, 'The time depth curve shows a well exactly on programme depth while its cost line runs high by 320,000 USD. Which explanation is ruled out?', '["A lump line that arrived rather earlier than the programme placed it, which lifts the money with no move in depth.", "A schedule slip, because late activities would have held the depth back while the per day lines kept billing.", "A rate that was understated when the estimate was built, which shows as money with no matching change in the hours the well has taken.", "An estimating difference on the per metre line for mud and consumables."]'::jsonb, 1, 'An estimating difference does not compound, so the gap it opens stays roughly the size it started at rather than growing with every shift.'),
  ('wellcost', 'advanced', 'final', null, 4, 'An unlabelled segment climbs at a steady 160,000 USD per day, makes no additional hole, and finishes with a vertical jump. Which activity type is it?', '["A drill activity, given that only a drilling activity raises the cumulative figure along the curve.", "A round trip, which bills the mud line on the metres covered while tripping and then steps at the end for the bit.", "A rig move at spud, where the cumulative figure is still climbing from zero.", "A casing run or another job that drills nothing, carrying a lump line linked to its own end."]'::jsonb, 3, 'Reading the shape this way lets an engineer name an activity from the curve alone, without being told which one it is.'),
  ('wellcost', 'advanced', 'final', null, 5, 'A lump for wellhead equipment is entered with no activity named against it. Where does it land, and what becomes of the endpoint?', '["It is refused, so the case will not run until a link has been supplied.", "It is dropped from the accrual while staying in the rollup, which leaves the curve finishing short of its base.", "It steps in at spud, and the endpoint still equals the base because nothing has been discarded.", "It lands at the end of the last activity, which keeps the endpoint right but puts the step in the wrong place along the way."]'::jsonb, 2, 'Placing it at spud rather than discarding it is what stops a missing link from turning into a silent shortfall.'),
  ('wellcost', 'advanced', 'final', null, 6, 'At 211.5 elapsed hours a night supervisor holds a cost report reading 2,600,000 USD beside the plan checkpoint. What has he established?', '["The size and the sign of the difference against the base, 340,000 USD over, and nothing about the authority.", "That the well will breach its approved figure of 5,918,000 USD.", "That the 538,000 USD provision has been consumed by that hour, because the curve carries the provision alongside the base cost.", "That the well is running late, given that more has been committed by this hour than the programme said it would be."]'::jsonb, 0, 'Nothing on the plan line is an actual, so its only value is as the reference against which a real cost report is read.'),
  ('wellcost', 'advanced', 'final', null, 7, 'Three of the five lumps, worth 1,500,000 USD between them, are still ahead at the published checkpoint. How should a comfortable position be read?', '["As a saving, since less has been committed than the plan allowed.", "As proof that the estimate was conservative, because a curve sitting comfortably at the middle of the schedule will sit comfortably at the end of it.", "As irrelevant, because those lumps are already inside the base subtotal.", "With caution, because most of the tangible spend has yet to arrive and it arrives as steps rather than slopes."]'::jsonb, 3, 'The two lumps behind the checkpoint are the 250,000 USD wellhead and the 300,000 USD cementing services.'),
  ('wellcost', 'advanced', 'final', null, 8, 'The last cell of a partner''s cumulative column reads 5,918,000 USD where its base subtotal reads 5,380,000 USD. What has the audit found?', '["A per day rate billed across productive hours instead of elapsed ones, which is the fault that leaves a model short.", "Contingency smeared into the accrual, since the drift is exactly the size of the 538,000 USD provision.", "A lump dropped from the accrual while it stayed in the rollup, which is the fault that leaves an endpoint standing above its own base subtotal.", "A correct model, because a cumulative column is meant to reach the approved total."]'::jsonb, 1, 'The subtraction takes about five seconds and needs no formula to be read, which is why it is worth running on every inherited model.'),
  ('wellcost', 'advanced', 'final', null, 9, 'Another submission finishes 320,000 USD short of its stated base. Which fault fits that figure exactly on the golden programme?', '["Per day lines applied across the 384 productive hours rather than across the full 432 elapsed hours.", "A wellhead lump that was left out of the accrual altogether.", "A contingency fraction entered as a share of the total instead of a share of the base, which shortens the accrual by the difference.", "A mud line billed on depth reached instead of on metres drilled."]'::jsonb, 0, 'The 48 allowance hours are two elapsed days, and at 160,000 USD a day that is the whole of the shortfall.'),
  ('wellcost', 'advanced', 'final', null, 10, 'A risked run reports its percentiles on base cost while approval is being sought on the total. What has to happen before the two can be compared?', '["Nothing at all, because a sampled percentile already carries a provision of its own inside every one of the realisations.", "The deterministic base has to be subtracted from the sampled mean.", "The contingency fraction has to be added to each sampled figure, because no provision accrues inside the run.", "The percentiles have to be relabelled in the cost convention before any comparison against an approved authority can be attempted at all."]'::jsonb, 2, 'The same design that keeps the provision off the curve keeps it out of the sampled totals, so the adjustment is one multiplication.'),
  ('wellcost', 'advanced', 'final', null, 11, 'Two rows of the published sweep share an endpoint of 5,380,000 USD although their totals differ by more than two million. What differs between them?', '["The non-productive fraction, which stretches the schedule.", "The number of activities, since a longer programme accrues more per day billing and therefore carries a larger total.", "The mix of tangible and intangible lines standing behind the same base.", "Only the contingency fraction, which changes the total while staying completely invisible to the curve."]'::jsonb, 3, 'Across the sweep the endpoint does move with the allowance fraction, from 5,060,000 USD at zero to 6,340,000 USD at 0.5.'),
  ('wellcost', 'advanced', 'final', null, 12, 'An imported case carries a completion lump pointing at an activity that no longer exists after the programme was reordered. What follows?', '["The lump is dropped and the endpoint lands below the base.", "The run is refused with an error, so a quietly short endpoint is never produced from the broken link.", "The lump is moved to the last activity in the reordered programme, which keeps the endpoint right and leaves the step in the wrong place.", "The lump is placed at spud, which is how the engine handles any activity link that it is unable to resolve."]'::jsonb, 1, 'A spreadsheet has no such guard, which is why the same fault there shows up only as a failed subtraction at the end.'),
  ('wellcost', 'advanced', 'final', null, 13, 'A spreadsheet''s cumulative column runs one row past the last activity of its schedule. Which half of the identity has broken?', '["The time half, because the final elapsed hour no longer equals the schedule total it was built from.", "The money half, since the extra row adds cost to the endpoint.", "Neither, provided the extra row carries no money, because only the money half of the identity is ever checked in practice.", "Both halves, since a row past the schedule moves the endpoint in hours and in money by the same proportion."]'::jsonb, 0, 'The usual cause is a lump parked at the bottom of the sheet with nowhere to attach itself.'),
  ('wellcost', 'advanced', 'final', null, 14, 'Why does the endpoint identity matter at all to the separate exercise of locating a deterministic total inside a sampled distribution?', '["It fixes which percentile convention the sampler will report in.", "It sets the contingency fraction that the chosen percentile has to cover.", "It guarantees the figure being ranked is internally consistent rather than quietly drifted from its own rollup.", "It does not matter, because a sampled distribution is built from the inputs and never touches the cost time curve at any point."]'::jsonb, 2, 'Ranking a total that does not agree with its own accrual measures the position of a number nobody should be quoting.'),
  ('wellcost', 'advanced', 'final', null, 15, 'A team proposes sampling the non-productive fraction alongside the two rates of penetration, on the grounds that trouble time varies. What is the flaw?', '["The fraction is not a quantity a triangular distribution can carry.", "It would move the curve endpoint, which is required to stay exactly equal to the base subtotal at all times.", "Nothing is wrong, provided the correlation between the allowance and the two rates is declared and applied by the sampler at the same time.", "The allowance is already a provision against trouble, so the same worry is counted twice and invisibly."]'::jsonb, 3, 'The published case holds both the allowance and the contingency fraction fixed for exactly this reason.'),
  ('wellcost', 'advanced', 'final', null, 16, 'Asked where the maximum of a lump range came from, a junior engineer cannot say. What is the correct treatment of that input?', '["Widen it further, since an undefended range should at least be generous.", "Leave it deterministic and record that it was, rather than inventing a spread to look suitably uncertain.", "Keep the range but halve it, because a narrow undefended range does less damage to a reported percentile than a wide one does.", "Replace the triangular with a uniform across the same two endpoints."]'::jsonb, 1, 'A lump still out to tender can usually be defended from quotes, which is what makes it a legitimate candidate for a range at all.'),
  ('wellcost', 'advanced', 'final', null, 17, 'If only one of the four published ranges could be tightened with fresh offset data, which one repays the work most?', '["The production hole rate, whose top is more than twice its bottom and whose hours drive the per day lines.", "The intermediate hole rate, which runs from 10 to 22 m per hour.", "The completion services lump, since its span from 350,000 to 800,000 USD is the widest of the four in plain dollars.", "The rig day rate, because it is the largest single line in the whole AFE."]'::jsonb, 0, 'Rate uncertainty compounds two ways, covering the widest ground relative to its own mode and entering eight of the ten activities.'),
  ('wellcost', 'advanced', 'final', null, 18, 'Offset data hints that a good hole could beat 22 m per hour, yet the case keeps a triangular of 10 to 22. What is that keeping asserting?', '["That 22 m per hour will be reached about one time in ten.", "That the sampler will extend the tail on its own once a draw arrives at the bound.", "That anything above 22 m per hour is impossible rather than merely unlikely, since density outside the bounds is zero.", "That the mean of the input sits at 22 m per hour, which is where a triangular puts its weight when the right tail is the longer one."]'::jsonb, 2, 'The shared module also carries uniform, normal and lognormal marginals, and a lognormal imposes no upper bound at all.'),
  ('wellcost', 'advanced', 'final', null, 19, 'Every activity in a case is priced at its most likely duration and the sponsor asks whether the answer is the expected cost. What is the honest reply?', '["Yes, because the most likely value of each input gives the most likely cost.", "No, since the mean of a triangular is the average of its three numbers and sits above a right skewed mode.", "No, but only where the uncertainties are rates, since a flat duration enters the cost by addition and can carry no skew of its own.", "Yes, provided the run has been seeded and its iteration count recorded next to the figure in the approval pack."]'::jsonb, 1, 'On the linear fixture that effect alone is worth 30,000 USD against a modal base of 1,500,000 USD.'),
  ('wellcost', 'advanced', 'final', null, 20, 'A correlation matrix built from offset wells comes back slightly short of positive definite. How does the shared module behave?', '["It rejects the matrix and falls back to independent draws.", "It samples the marginals as normal and applies no copula to them at all.", "It rescales every declared correlation until the matrix is positive definite again, changing the pairs you asked for without saying so.", "Its Cholesky routine clamps the diagonal at zero, so the run degrades gracefully instead of returning NaN."]'::jsonb, 3, 'The copula imposes correlation on the joint pattern only, so each input keeps exactly the marginal shape that was specified for it.'),
  ('wellcost', 'advanced', 'final', null, 21, 'A developer offers to build a triangular draw straight into the well cost engine so that callers need not assemble one. What should the reviewer say?', '["Refuse it, because a second sampler means a second seed discipline and a second percentile convention.", "Accept it, provided the engine''s own seed is always kept matched to the one that the shared module is using.", "Refuse it, because triangular is the wrong marginal for a rate of penetration.", "Accept it, since the engine already evaluates a schedule and an AFE, so drawing one more number is a small addition to work it does anyway."]'::jsonb, 0, 'Keeping the evaluator deterministic is also what makes every published percentile reproducible from the sampled inputs alone.'),
  ('wellcost', 'advanced', 'final', null, 22, 'A contractor promises a crew that runs casing ten times faster on the 2,000 m string that currently takes 39 hours. How much of that actually comes off?', '["Thirty five hours, since the running term is nearly all of the job.", "Nothing, because casing hours are stated flat rather than produced by a speed.", "Eighteen hours, taking the job to 21, because 19 hours of flat time do not answer to speed at all.", "All but a few minutes, since the running term shrinks towards zero and a casing activity holds no other term to keep the hours up."]'::jsonb, 2, 'Pushing the speed to 5,000 m per hour still leaves 19.4 hours, which is the floor worth knowing before anyone promises savings.'),
  ('wellcost', 'advanced', 'final', null, 23, 'Citing the fixture''s two per cent gap, a planner applies a flat two per cent uplift to every rate driven estimate. Where does the reasoning fail?', '["It fails only in size, because the true uplift from curvature is nearer one per cent.", "That gap is pure input skew, since all four of the fixture''s uncertainties enter the cost linearly.", "It does not fail, since the fixture and the golden case share the same four uncertainties and so the same shape of answer.", "The gap is a sampling error of the kind that disappears once the iteration count is raised far enough."]'::jsonb, 1, 'Curvature is a second and separate lift that appears only once a sampled rate sits in a denominator, and its size has to be measured.'),
  ('wellcost', 'advanced', 'final', null, 24, 'Hours on the 1,500 m section run plus 50 and minus 25 around plan under a window of plus or minus 5 m per hour. What follows for a symmetric provision?', '["It is correct, because cost follows time linearly once the window is fixed.", "It is the wrong sign, since the downside in hours is the smaller of the two.", "It is right in the mean and wrong in the tails, since the per day rate applies to hours saved and hours lost alike and so cancels the asymmetry.", "It is the wrong shape, covering twice the upside it needs while covering half of the downside it was set against."]'::jsonb, 3, 'Widening the window to plus or minus 10 m per hour makes it worse still, at 200 hours lost against 40 gained.'),
  ('wellcost', 'advanced', 'final', null, 25, 'A reviewer wants the analytic mean of the golden risk case as a cross check on the sampled one. What should he be told?', '["There is none available, because two of its four uncertainties are rates and time goes as one over rate.", "It is simply the run at the modes, which a closed form of this kind reproduces exactly whatever the inputs.", "It can be assembled from the four input means, since the mean of a sum is the sum of the means whatever shapes the inputs happen to carry.", "It equals the sampled mean once the iteration count passes two thousand."]'::jsonb, 0, 'Writing the variance instead would need moments of a sum of reciprocals of different triangulars, which no standard result covers.'),
  ('wellcost', 'advanced', 'final', null, 26, 'An estimate arrives as a band drawn around a finished total, and the well then slips by two days. What can that band not say?', '["How wide the spread of outcomes is on the well as it was costed.", "Which percentile convention its two endpoints were written in.", "Which lines the slip touches, because it never knew that 53.53 per cent of the base bills per day.", "What the median outcome is, since a shape drawn by hand has no middle that anybody could read off it and quote in a meeting."]'::jsonb, 2, 'Sampling the inputs preserves that structure, while sampling the answer discards it and then asks for trust in the picture.'),
  ('wellcost', 'advanced', 'final', null, 27, 'Rerunning a case at several seeds, an analyst reports only the run that returned the friendliest P50. What is that practice?', '["Sound, because a seeded run reproduces whichever seed was chosen.", "Fraud with extra steps, since the honest use of several seeds is to measure the wobble and then quote one.", "Acceptable at a high enough iteration count, because the seeds converge on one another and the choice between them stops mattering.", "Harmless, since a seed is in no sense a claim about the truth of whichever answer comes back from the run."]'::jsonb, 1, 'Seed 42 is not more correct than any other, which is precisely why the one that was used has to be named.'),
  ('wellcost', 'advanced', 'final', null, 28, 'To be safe, a range on rate of penetration is entered with a minimum of zero. What happens when the sampler reaches a draw at that bound?', '["The draw is resampled until it lands inside a valid range.", "The activity returns its flat term only, because the running term goes to zero hours.", "The run continues and reports percentiles built from the realisations that survived, with a note recording how many were discarded along the way.", "The realisation throws, since a rate of penetration of zero is refused rather than quietly clipped."]'::jsonb, 3, 'Sampling loosens none of the deterministic checks, and the failure is raised on the realisation that produced it.'),
  ('wellcost', 'advanced', 'final', null, 29, 'Which field of the shared sampler holds the conservative cost case, and how should it be captioned on a slide?', '["The field named p10, captioned in words as the cost that will not be exceeded nine times out of ten.", "The field named p90, captioned as the conservative cost case.", "The field named p50, since it is the only percentile carrying the same meaning in both of the conventions in daily use.", "Either tail field, provided the caption states which convention was used."]'::jsonb, 0, 'The module sorts ascending and crosses its tail labels over, because it was written for reserves rather than for costs.'),
  ('wellcost', 'advanced', 'final', null, 30, 'A base of 5,380,000 USD is measured at the fortieth percentile of its own distribution in the cost convention. Is the estimate wrong?', '["Yes, since any figure presented as a plan is required to sit at or above the median of its own distribution.", "Yes, because a deterministic run ought to reproduce the sampled mean.", "No, but it is a low case being presented as a plan, and the approvers should know that before they vote.", "No, and nothing at all follows from the measurement, because a deterministic total is a single point and has no place in a distribution."]'::jsonb, 2, 'Saying where a number sits is a fact that can be acted on, whereas calling the same number realistic is only an opinion.'),
  ('wellcost', 'advanced', 'final', null, 31, 'The business states the confidence it is prepared to fund. How should a contingency fraction then be derived from that statement?', '["Take the last well''s fraction and adjust it for the new spread.", "Apply a fraction first and then read off whichever percentile the total reaches.", "Divide the sampled standard deviation by the base cost, which converts the confidence the business asked for into a fraction of that base.", "Read the cost at that percentile, subtract the base, and express the difference as a fraction of the base."]'::jsonb, 3, 'Working in that direction gives the provision a reason rather than a precedent, which is the difference the lesson is after.'),
  ('wellcost', 'advanced', 'final', null, 32, 'Pressed to cut a provision because it outranks a contracted service line, what does the golden case''s own ranking actually show?', '["It ranks second of the nine lines at the golden fraction, behind the rig.", "At a fraction of 0.1 it already ranks fourth of the nine lines, and it passes the largest at 0.3346.", "It never outranks a contracted line, because a provision is not a line and so is never ranked among them at all.", "It ranks below every contracted line until the fraction has reached 0.5."]'::jsonb, 1, 'A line that size deserves to be looked at directly, which is the second argument for keeping it off the accrual.'),
  ('wellcost', 'advanced', 'final', null, 33, 'A converged run reports a coefficient of variation of 0.0417 and the team calls the well low risk. What is the mistake?', '["That figure describes four chosen triangulars rather than the well, and it shrinks whenever the ranges narrow.", "The coefficient of variation should have been read against the median of that run rather than against its own mean.", "A coefficient of variation cannot be formed on a cost distribution, because costs are right skewed and the mean is pulled by the tail.", "The run has not converged, since 2,000 iterations leave the tails noisy."]'::jsonb, 0, 'The same figure belongs to the linear fixture, whose standard deviation is 63868.354187866 USD on a mean of 1,530,000 USD.'),
  ('wellcost', 'advanced', 'final', null, 34, 'How can a team tell whether uncertainty is genuinely the thing holding up a decision?', '["Raise the iteration count until the reported percentiles stop moving.", "Widen every range by a fixed proportion and reread the two tail figures.", "Run the case on the ranges they would defend and again on the ranges they fear, then see if the decision holds.", "Compare the coefficient of variation against the published fixture value and treat anything larger as a decision that uncertainty controls."]'::jsonb, 2, 'If the decision flips, the exercise has named the single assumption that deserves the argument.'),
  ('wellcost', 'advanced', 'final', null, 35, 'Ten wells of one campaign are being budgeted together. Which of the mean and the median belongs in the portfolio figure?', '["The median, since half of the wells will come in below it.", "The mean, because averages add across wells while the median answers only for the single well in hand.", "Neither, because a portfolio figure has to be built on a tail percentile if it is to carry any confidence statement at all.", "The median, since it is the one figure that both conventions agree on."]'::jsonb, 1, 'Neither of them is the deterministic base cost, whose own rank has to be measured before it can be quoted alongside either.'),
  ('wellcost', 'advanced', 'final', null, 36, 'Summarising the tier in a handover note, a colleague writes that estimates are uncertain. Why does that miss the point?', '["It confuses the mean of a distribution with its median.", "It understates the spread, given that a properly sampled run on a case like this one reports a far wider range.", "It is true as far as it goes but omits the seed and the iteration count, without which no reported figure can be rebuilt by anybody else.", "The claim here is sharper, that the standard way of building an estimate has a measurable direction of error."]'::jsonb, 3, 'The direction is known in advance because time goes as one over rate, so a base built on likely rates lands low.'),
  ('wellcost', 'advanced', 'final', null, 37, 'A finance director asks why a well should be funded above the engineer''s own best estimate. What is the argument to give him?', '["Most likely rates yield the cost of most likely rates, which is optimistic before anybody has been careless.", "Because the approved total always exceeds the base by the provision.", "Because the non-productive allowance is a stretch applied to productive time.", "Because a deterministic run at the modes cannot be reproduced without a seed, and an unreproducible figure should never be funded on its own."]'::jsonb, 0, 'The right size for the gap is not a habit but a percentile, read from the sampled distribution and stated in a named convention.'),
  ('wellcost', 'advanced', 'final', null, 38, 'Handed a partner AFE and half an hour before the meeting, which single check should come first?', '["Check that every percentile carries its convention written in words.", "Compare the contingency fraction with the one your own last well used.", "Subtract the base from the final cumulative figure, since a non-zero result condemns everything downstream.", "Confirm that the sampled mean exceeds the deterministic total, which is the diagnostic that catches a reversed range on a rate."]'::jsonb, 2, 'That check costs nothing to run and catches a total that is internally inconsistent rather than merely wrong.'),
  ('wellcost', 'advanced', 'final', null, 39, 'Word arrives that a well will take two more days than programmed. Which of the nine lines move, and by how much?', '["Every line, in proportion to its share of the 5,380,000 USD base.", "Only the per day lines, at 160,000 USD a day, so 320,000 USD on a base whose lumps and metres do not stir.", "The per day lines and the per metre line, since a longer well drills further and mud is consumed for as long as the rig stays on location.", "None of them, because the non-productive allowance in the plan already carries a slip of exactly that size."]'::jsonb, 1, 'Elasticity to elapsed days is 1.0 on a per day line and 0.0 on a per metre or lump line, which is what makes the basis the thing to check.'),
  ('wellcost', 'advanced', 'final', null, 40, 'Of the items recorded beside a risked total, which one goes missing first and what does losing it cost?', '["The iteration count, which sets how noisy the reported tails are.", "The engine version, which fixes what the deterministic evaluator did.", "The correlation applied, which is the one item that shifts a reported mean and therefore the one that cannot be reconstructed later.", "The seed, which feels like plumbing, and without it no reviewer can land on those same figures again."]'::jsonb, 3, 'Correlation is worth recording too, but what it changes is the spread rather than any mean in the run.'),
  ('wellcost', 'advanced', 'final', null, 41, 'A post well report offers a single overspend figure against the approved total. What has to be rebuilt before it teaches anything?', '["The activity structure filled with what the rig did, so that each variance has an owner instead of a total.", "The risked distribution, rerun at the seed that the original estimate carried, so the overspend can be ranked.", "The cost time curve, redrawn on productive hours so as to isolate the delay.", "The contingency line, since an overspend means nothing until the provision meant to absorb it has been taken back out of the total."]'::jsonb, 0, 'A well whose intermediate section ran long while every line billed as costed is far more informative than one that simply came in over.'),
  ('wellcost', 'advanced', 'final', null, 42, 'A planner has one previous well in the field and wants ranges for the next. What does that single well actually support?', '["A triangular whose mode is that well''s own achieved rate.", "Nothing whatever, because ranges have to be drawn from published literature.", "Very little, because one outcome fixes no spread and it takes a set of recorded wells to make a range.", "A complete set of ranges, provided both wells share a rig and a crew, which is what makes one outcome transferable to the next."]'::jsonb, 2, 'Ten wells with their rates and their non-productive time honestly recorded turn a range from an opinion into a measurement.');
